const targets=await(await fetch('http://127.0.0.1:9338/json/list')).json();const page=targets.find(p=>p.type==='page');const ws=new WebSocket(page.webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);ws.send(JSON.stringify({id:1,method:'Runtime.evaluate',params:{expression:'if(workbench.state.tasks.some(t=>["queued","starting","running","waiting","stopping"].includes(t.state)))throw Error("有活动任务");window.close()'}}));await new Promise(r=>{ws.onclose=r;setTimeout(r,1000)});ws.close();console.log('已关闭本轮独立验证窗口');
